labs.solution:
function once(fn) {
  let called = false;
  let result;
  return (...args) => {
    if (!called) {
      called = true;
      result = fn(...args);
    }
    return result;
  };
}

function makeStepCounter(step) {
  let n = 0;
  return () => (n += step);
}

function createStack() {
  const items = [];
  return {
    push(v) { items.push(v); },
    pop() { return items.pop(); },
    peek() { return items[items.length - 1]; },
    size() { return items.length; },
  };
}

function curry(fn) {
  return function curried(...args) {
    return args.length >= fn.length ? fn(...args) : (...more) => curried(...args, ...more);
  };
}

function makeToggle(a, b) {
  let first = true;
  return () => {
    const v = first ? a : b;
    first = !first;
    return v;
  };
}

function makeHistory() {
  const items = [];
  return {
    add(v) { items.push(v); },
    undo() { return items.pop(); },
    list() { return [...items]; },
  };
}

function after(n, fn) {
  let calls = 0;
  return (...args) => (++calls >= n ? fn(...args) : undefined);
}

function uniqueFilter() {
  const seen = new Set();
  return (v) => {
    if (seen.has(v)) return false;
    seen.add(v);
    return true;
  };
}

