function mergeDeep(a, b) {
  const out = { ...a };
  for (const k of Object.keys(b)) {
    const x = a[k];
    const y = b[k];
    const isObj = (v) => v !== null && typeof v === "object" && !Array.isArray(v);
    out[k] = isObj(x) && isObj(y) ? mergeDeep(x, y) : y;
