}

async function onlyFulfilled(promises) {
  const r = await Promise.allSettled(promises);
  return r.filter((x) => x.status === "fulfilled").map((x) => x.value);
}

async function waitAll(obj) {
  const keys = Object.keys(obj);
  const values = await Promise.all(keys.map((k) => obj[k]));
  return Object.fromEntries(keys.map((k, i) => [k, values[i]]));
}

function firstRejection(promises) {
  return Promise.all(promises).then(() => null, (e) => e.message);
}

async function statuses(promises) {
  return (await Promise.allSettled(promises)).map((r) => r.status);
}

