function createRegistry() {
  const defs = new Map();
  const cache = new Map();
  const api = {
    define(name, deps, factory) {
      defs.set(name, { deps, factory });
    },
    require(name) {
      if (cache.has(name)) return cache.get(name);
      const d = defs.get(name);
      if (!d) throw new Error("unknown: " + name);
      const value = d.factory(...d.deps.map((x) => api.require(x)));
      cache.set(name, value);
      return value;
    },
  };
  return api;
}

function resolveOrder(graph) {
  const out = [];
  const state = {};
  function visit(n) {
    if (state[n] === 2) return;
    if (state[n] === 1) throw new Error("cycle");
    state[n] = 1;
    for (const d of graph[n] || []) visit(d);
    state[n] = 2;
    out.push(n);
  }
  Object.keys(graph).forEach(visit);
  return out;
}

function hasCycle(graph) {
  const state = {};
  function visit(n) {
    if (state[n] === 2) return false;
    if (state[n] === 1) return true;
    state[n] = 1;
    for (const d of graph[n] || []) if (visit(d)) return true;
    state[n] = 2;
    return false;
  }
  return Object.keys(graph).some(visit);
}

function makeNamespace(obj) {
  return Object.freeze({ ...obj });
}

function makeCounterModule() {
  let count = 0;
  return {
    get count() {
      return count;
    },
    increment() {
      count++;
    },
  };
}

function makeLoader(registry) {
  const cache = new Map();
  return (name) => {
    if (!cache.has(name)) {
      cache.set(name, registry[name] ? registry[name]() : Promise.reject(new Error("no module: " + name)));
    }
    return cache.get(name);
  };
}

function parseImports(source) {
  const out = [];
  const re = /import\s+(?:[^'"]*?\s+from\s+)?['"]([^'"]+)['"]/g;
  let m;
  while ((m = re.exec(source))) out.push(m[1]);
  return out;
}

function barrel(modules) {
  const out = {};
  for (const m of modules) {
    for (const k of Object.keys(m)) {
      if (k in out) throw new Error("duplicate: " + k);
      out[k] = m[k];
    }
  }
  return out;
}

