function countNodes(tree) {
  if (!tree.tag) return 0;
  return 1 + (tree.children || []).reduce((s, c) => s + countNodes(c), 0);
}

function findByTag(tree, tag) {
  const out = [];
  (function walk(n) {
    if (n.tag === tag) out.push(n.id);
    (n.children || []).forEach(walk);
  })(tree);
  return out;
}

function closest(node, pred) {
  let n = node;
  while (n) {
    if (pred(n)) return n;
    n = n.parent;
  }
  return null;
}

function matches(node, selector) {
  if (selector.startsWith("#")) return node.id === selector.slice(1);
  if (selector.startsWith(".")) return (node.classes || []).includes(selector.slice(1));
  return node.tag === selector;
}

function textContent(node) {
  if (node.text !== undefined) return node.text;
  return (node.children || []).map(textContent).join("");
}

function depth(tree) {
  return 1 + Math.max(0, ...(tree.children || []).map(depth));
}

function toHtml(node) {
  if (node.text !== undefined) return node.text;
  const attrs = Object.entries(node.attrs || {}).map(([k, v]) => " " + k + '="' + v + '"').join("");
  return "<" + node.tag + attrs + ">" + (node.children || []).map(toHtml).join("") + "</" + node.tag + ">";
}

