function bubblePath(node) {
  const out = [];
  for (let n = node; n; n = n.parent) out.push(n.tag);
  return out;
}

function dispatch(target, type) {
  const log = [];
  let stopped = false;
  const event = { type, target, stopPropagation() { stopped = true; } };
  let n = target;
  while (n && !stopped) {
    event.currentTarget = n;
    for (const h of (n.handlers && n.handlers[type]) || []) h(event);
    log.push(n.tag);
    n = n.parent;
  }
  return log;
}

function delegate(root, matchFn, handler) {
  return (event) => {
    let n = event.target;
    while (n && n !== root) {
      if (matchFn(n)) {
        handler(n, event);
        return;
      }
      n = n.parent;
    }
  };
}

function makeEventTarget() {
  const map = new Map();
  return {
    addEventListener(type, fn, opts = {}) {
      if (!map.has(type)) map.set(type, []);
      map.get(type).push({ fn, once: !!opts.once });
    },
    dispatchEvent(type, data) {
      const list = map.get(type) || [];
      for (const l of [...list]) {
        if (l.once) list.splice(list.indexOf(l), 1);
        l.fn(data);
      }
    },
  };
}

function makeEvent(type, cancelable) {
