function makeDragTracker() {
  let start = null;
  return (e) => {
    if (e.type === "down") {
      start = { x: e.x, y: e.y };
      return { dragging: true, dx: 0, dy: 0 };
    }
    if (!start) return { dragging: false, dx: 0, dy: 0 };
    const dx = e.x - start.x;
    const dy = e.y - start.y;
    if (e.type === "up") {
      start = null;
      return { dragging: false, dx, dy };
    }
    return { dragging: true, dx, dy };
  };
}

function makeDoubleClick(ms) {
  let last = null;
  return (time) => {
    if (last !== null && time - last <= ms) {
      last = null;
      return true;
    }
    last = time;
    return false;
  };
}

function serializeForm(fields) {
  const out = {};
  for (const f of fields) {
    if (!f.name || f.disabled) continue;
    if ((f.type === "checkbox" || f.type === "radio") && !f.checked) continue;
    out[f.name] = f.value;
  }
  return out;
}

function validateForm(values, rules) {
  const errors = {};
  for (const field of Object.keys(rules)) {
    const r = rules[field];
    const v = values[field] || "";
    if (r.required && v === "") errors[field] = "required";
    else if (r.minLength && v.length < r.minLength && v !== "") errors[field] = "min " + r.minLength;
    else if (r.pattern && v !== "" && !r.pattern.test(v)) errors[field] = "invalid";
  }
  return errors;
}

