  };
}

function throttle(fn, ms) {
  let last = -Infinity;
  return (...args) => {
    const now = Date.now();
    if (now - last >= ms) {
      last = now;
      return fn(...args);
    }
  };
}

function tickN(n, ms) {
  return new Promise((resolve) => {
    let count = 0;
    const id = setInterval(() => {
      if (++count === n) {
        clearInterval(id);
        resolve(count);
      }
    }, ms);
  });
}

function cancelableTimeout(fn, ms) {
  const id = setTimeout(fn, ms);
  return () => clearTimeout(id);
}

