async function pollUntil(check, ms, maxTries) {
  for (let i = 0; i < maxTries; i++) {
    if (await check()) return true;
    await new Promise((r) => setTimeout(r, ms));
  }
  return false;
}

function memoizeTTL(fn, ttl) {
  const cache = new Map();
  return (x) => {
    const hit = cache.get(x);
    if (hit && Date.now() - hit.at < ttl) return hit.value;
    const value = fn(x);
    cache.set(x, { value, at: Date.now() });
    return value;
  };
}

function countdown(n, onTick) {
  return new Promise((resolve) => {
    const step = (i) => {
      if (i === 0) {
        resolve();
        return;
      }
      onTick(i);
      setTimeout(() => step(i - 1), 1);
    };
    step(n);
  });
}

function rateLimiter(max, windowMs) {
  let start = Date.now();
  let count = 0;
  return () => {
    const now = Date.now();
    if (now - start >= windowMs) {
      start = now;
      count = 0;
    }
    if (count < max) {
      count++;
      return true;
    }
    return false;
  };
}

function debounceFull(fn, ms) {
  let t = null;
  let lastArgs;
  const d = (...args) => {
    lastArgs = args;
    clearTimeout(t);
    t = setTimeout(() => {
      t = null;
      fn(...lastArgs);
    }, ms);
  };
  d.cancel = () => {
    clearTimeout(t);
    t = null;
  };
  d.flush = () => {
    if (t) {
      clearTimeout(t);
      t = null;
      fn(...lastArgs);
    }
  };
  return d;
}

function makeTimers() {
  const ids = new Set();
  return {
    after(fn, ms) {
      const id = setTimeout(() => {
        ids.delete(id);
        fn();
      }, ms);
      ids.add(id);
    },
    clearAll() {
      ids.forEach(clearTimeout);
      ids.clear();
    },
  };
}

