function makeBoundedCache(max) {
  const m = new Map();
  return {
    set(k, v) {
      m.set(k, v);
      if (m.size > max) m.delete(m.keys().next().value);
    },
    get(k) {
      return m.get(k);
    },
    size() {
      return m.size;
    },
  };
}

function memoizeObj(fn) {
  const cache = new WeakMap();
  return (obj) => {
    if (!cache.has(obj)) cache.set(obj, fn(obj));
    return cache.get(obj);
  };
}

function makeSubscription() {
  const subs = new Set();
  return {
    subscribe(fn) {
      subs.add(fn);
      return () => subs.delete(fn);
    },
    notify(v) {
      subs.forEach((fn) => fn(v));
    },
    count() {
      return subs.size;
    },
  };
}

function createPool(create) {
  const free = [];
  return {
    acquire() {
      return free.length ? free.pop() : create();
    },
    release(obj) {
