  };
}

function hasCircular(obj) {
  const path = new Set();
  function walk(o) {
    if (o === null || typeof o !== "object") return false;
    if (path.has(o)) return true;
    path.add(o);
    const found = Object.values(o).some(walk);
    path.delete(o);
    return found;
  }
  return walk(obj);
}

function countReachable(root) {
  const seen = new Set();
  (function mark(o) {
    if (o === null || typeof o !== "object" || seen.has(o)) return;
    seen.add(o);
    Object.values(o).forEach(mark);
  })(root);
  return seen.size;
}

